SELECT (DATE_TRUNC('DAY', "BALANCE_DAY")) AS "TIME_BUCKET", MIN(COMMITMENT_REMAINING) AS "ORG_COMMITMENT_REMAINING" FROM (SELECT b."CONTRACT_NUMBER" AS CONTRACT_NUMBER, b."ORGANIZATION_NAME" AS ORGANIZATION_NAME, b."CURRENCY" AS CURRENCY, CAST(b."DATE" AS DATE) AS BALANCE_DAY, (CAST(b."FREE_USAGE_BALANCE" AS DECIMAL(38, 9))) AS FREE_USAGE_BALANCE, (CAST(b."ROLLOVER_BALANCE" AS DECIMAL(38, 9))) AS ROLLOVER_BALANCE, (CAST(b."CAPACITY_BALANCE" AS DECIMAL(38, 9))) AS CAPACITY_BALANCE, (CAST(b."ON_DEMAND_CONSUMPTION_BALANCE" AS DECIMAL(38, 9))) AS ON_DEMAND_BALANCE, (CAST(b."FREE_USAGE_BALANCE" + b."ROLLOVER_BALANCE" + b."CAPACITY_BALANCE" AS DECIMAL(38, 9))) AS COMMITMENT_REMAINING, (CAST(c.COMMITMENT_TOTAL AS DECIMAL(38, 9))) AS COMMITMENT_TOTAL, (CAST(c.COMMITMENT_TOTAL - (b."FREE_USAGE_BALANCE" + b."ROLLOVER_BALANCE" + b."CAPACITY_BALANCE") AS DECIMAL(38, 9))) AS COMMITMENT_CONSUMED, (CAST(LAG(b."FREE_USAGE_BALANCE" + b."ROLLOVER_BALANCE" + b."CAPACITY_BALANCE") OVER (PARTITION BY b."CONTRACT_NUMBER" ORDER BY CAST(b."DATE" AS DATE)) - (b."FREE_USAGE_BALANCE" + b."ROLLOVER_BALANCE" + b."CAPACITY_BALANCE") AS DECIMAL(38, 9))) AS COMMITMENT_DRAW FROM remaining_balance_daily AS b LEFT JOIN (SELECT "CONTRACT_NUMBER" AS CONTRACT_NUMBER, (CAST(SUM("AMOUNT") AS DECIMAL(38, 9))) AS COMMITMENT_TOTAL FROM contract_items GROUP BY 1) AS c ON c.CONTRACT_NUMBER = b."CONTRACT_NUMBER") AS base GROUP BY (DATE_TRUNC('DAY', "BALANCE_DAY")) ORDER BY "ORG_COMMITMENT_REMAINING" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
